// Kontrollerar F47 "Alt-text för porträtt": avatar() ger alt="Namn, AI-skapat porträtt",
// namnet escapas, inga porträtt med tom alt, och en rad på tillgänglighetssidan.
// AI-skapat (B-051). Generated by AI, Directed by MS.
const fs = require('fs');
const path = require('path');
const vm = require('vm');

const html = fs.readFileSync('public/index.html', 'utf8');

// Plocka ut function avatar(...) { ... } med klammerräkning.
function plockaFunktion(src, namn) {
  const start = src.indexOf('function ' + namn + '(');
  if (start < 0) return null;
  let i = src.indexOf('{', start), djup = 0;
  for (; i < src.length; i++) {
    if (src[i] === '{') djup++;
    else if (src[i] === '}') { djup--; if (djup === 0) return src.slice(start, i + 1); }
  }
  return null;
}

const avatarSrc = plockaFunktion(html, 'avatar');
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const ctx = {
  esc,
  statusOf: () => null,
  initials: n => (n || '?').trim().charAt(0),
  lanternSvg: () => '<svg></svg>',
};
vm.createContext(ctx);
let avatar = null;
try { vm.runInContext(avatarSrc + '; this.avatar = avatar;', ctx); avatar = ctx.avatar; } catch (e) { avatar = null; }

const teo = avatar ? avatar({ id: 'teo-lindberg', name: 'Teo Lindberg', photo: '/img/portratt/teo-lindberg.jpg' }) : '';
const ekLin = avatar ? avatar({ id: 'ek-lin', name: 'Ek & Lin', photo: '/img/portratt/ek-lin.jpg' }) : '';
const utanBild = avatar ? avatar({ id: 'x', name: 'Utan Bild' }) : '';

// Alla <img> i public/*.html och public/*.js med img/portratt/ i src ska ha en icke-tom alt.
const filer = fs.readdirSync('public').filter(f => /\.(html|js)$/.test(f)).map(f => path.join('public', f));
const tommaAlt = [];
for (const f of filer) {
  const txt = fs.readFileSync(f, 'utf8');
  for (const m of txt.matchAll(/<img\b[^>]*>/g)) {
    const tag = m[0];
    if (!/src="[^"]*img\/portratt\//.test(tag)) continue;
    if (!/\balt="[^"]+"/.test(tag)) tommaAlt.push(f + ': ' + tag.slice(0, 80));
  }
}

const tg = fs.readFileSync('public/tillganglighet.html', 'utf8');
const tbody = (tg.match(/<tbody>([\s\S]*?)<\/tbody>/) || [])[1] || '';

const krav = {
  avatarFinns: typeof avatar === 'function',
  avatarAlt: teo.includes('<img') && teo.includes('alt="Teo Lindberg, AI-skapat porträtt"'),
  escapat: ekLin.includes('alt="Ek &amp; Lin, AI-skapat porträtt"'),
  initialerOrorda: !utanBild.includes('<img') && utanBild.includes('class="ini"'),
  ingenTomAlt: tommaAlt.length === 0,
  tillganglighetRad: /<td>[^<]*AI-skapat porträtt[^<]*<\/td>/.test(tbody.replace(/&rdquo;/g, '')),
  tillganglighetUtanSkript: !/<script/i.test(tg),
};
const ok = Object.values(krav).every(Boolean);
console.log(JSON.stringify({ ...krav, tommaAlt, ok }));
process.exit(ok ? 0 : 1);
